c + o &= u \\
u + n &= t \\
t + c &= s \\
o + n + s &= 12
\end{align*}

Let $g(x)$ be a function piecewise defined as \[g(x) = \left\{
\begin{array}{cl}
-x & x\le 0, \\
2x-41 & x>0.
\end{array}
\right.\] If $a$ is negative, find $a$ so that $g(g(g(10.5)))=g(g(g(a)))$.

A point $P$ is randomly placed in the interior of the right triangle below.  What is the probability that the area of triangle $PBC$ is less than half of the area of triangle $ABC$?  Express your answer as a common fraction. [asy]
size(7cm);
defaultpen(linewidth(0.7));
pair A=(0,5), B=(8,0), C=(0,0), P=(1.5,1.7);
draw(A--B--C--cycle);
draw(C--P--B);
label("$A$",A,NW);
label("$B$",B,E);
label("$C$",C,SW);
label("$P$",P,N);
draw((0,0.4)--(0.4,0.4)--(0.4,0));[/asy]

Find $AX$ in the diagram.

[asy]

import markers;

real t=.56;

pair A=(0,0);

pair B=(3,2);

pair C=(.5,1.5);

pair X=t*A+(1-t)*B;

draw(C--A--B--C--X);

label("$A$",A,SW);

label("$B$",B,E);

label("$C$",C,N);

label("$X$",X,SE);

markangle(n=1,radius=15,A,C,X,marker(markinterval(stickframe(n=1),true)));

markangle(n=1,radius=15,X,C,B,marker(markinterval(stickframe(n=1),true)));

label("$24$",.5*(B+X),SE);

label("$28$",.5*(B+C),N);

label("$21$",.5*(A+C),NW);

[/asy]

